source("_common.R")
cases <- list()
for (z in c(-8, -3.2, -1.96, -0.5, 0, 0.3, 1.644854, 2.5, 6)) cases[[length(cases)+1]] <- list(f="pnorm", x=z, v=pnorm(z))
for (p in c(1e-10, 0.001, 0.025, 0.1, 0.5, 0.8, 0.975, 0.999, 1-1e-9)) cases[[length(cases)+1]] <- list(f="qnorm", x=p, v=qnorm(p))
for (df in c(1, 2.5, 5, 30, 1000)) for (t in c(-4, -1, 0.7, 2.1)) cases[[length(cases)+1]] <- list(f="pt", x=t, df=df, v=pt(t, df))
for (df in c(1, 3, 9, 29, 200)) for (p in c(0.005, 0.025, 0.9, 0.975)) cases[[length(cases)+1]] <- list(f="qt", x=p, df=df, v=qt(p, df))
for (df in c(1, 2, 7, 40)) for (x in c(0.01, 1, 3.84, 15, 80)) cases[[length(cases)+1]] <- list(f="pchisq_upper", x=x, df=df, v=pchisq(x, df, lower.tail=FALSE))
for (df in c(1, 4, 25)) for (p in c(0.025, 0.5, 0.95, 0.999)) cases[[length(cases)+1]] <- list(f="qchisq", x=p, df=df, v=qchisq(p, df))
for (d in list(c(2,10), c(5,40), c(1,1))) for (x in c(0.2, 1, 4.5)) cases[[length(cases)+1]] <- list(f="pf_upper", x=x, df=d[1], df2=d[2], v=pf(x, d[1], d[2], lower.tail=FALSE))
for (ab in list(c(0.5,0.5), c(2,8), c(30, 400), c(1, 3))) for (x in c(0.01, 0.2, 0.7)) cases[[length(cases)+1]] <- list(f="pbeta", x=x, a=ab[1], b=ab[2], v=pbeta(x, ab[1], ab[2]))
for (ab in list(c(1,99), c(5,46), c(0.5, 10.5))) for (p in c(0.025, 0.975)) cases[[length(cases)+1]] <- list(f="qbeta", x=p, a=ab[1], b=ab[2], v=qbeta(p, ab[1], ab[2]))
for (k in c(0, 3, 10)) cases[[length(cases)+1]] <- list(f="binom_test", k=k, n=40, p0=0.1, v=binom.test(k, 40, 0.1)$p.value)
for (x in c(0.5, 3, 10.2, 150)) cases[[length(cases)+1]] <- list(f="lgamma", x=x, v=lgamma(x))
write_ref(list(cases = cases), "distributions")
